const std::size_t word_size = std::size_t(8) * std::size_t(sizeof(std::uintptr_t));
const std::size_t max_bits = binfo->size_bits;
const std::size_t max_words = (max_bits + word_size - 1) / word_size;

for (std::size_t word_idx = 0; word_idx < max_words; ++word_idx) {
    std::uintptr_t word = bitmap[word_idx];
    if (word != std::uintptr_t(-1)) {
        std::size_t bit_pos = std::countr_zero(word);
        std::size_t bit_idx = word_idx * word_size + bit_pos;

        if (bit_idx >= max_bits) {
            continue;  // Skip if beyond bitmap size
        }

        std::uintptr_t expected = word;
        std::uintptr_t desired = word | (std::uintptr_t(1) << bit_pos);

        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic_uintptr_t*>(&bitmap[word_idx]),
                &expected,
                desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return bit_idx;
        }
    }
}
return max_bits;  // No unset bits found
// END_CODE

